/** A genre's tracks in curated play order. */
export function tracksForGenre(genreId: string): LibraryTrack[] {
  return LIBRARY_TRACKS.filter((t) => t.genreId === genreId);
}

/** Find a library track by its stable id. */
export function libraryTrack(id: string): LibraryTrack | undefined {
  return LIBRARY_TRACKS.find((t) => t.id === id);
}
